import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path

class Extract(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.blocks = []
        self.links = []
        self.current = None
    def handle_starttag(self, tag, attrs):
        if tag in {'p', 'li', 'h2', 'h3', 'blockquote', 'tr'}:
            self.current = []
        if tag == 'a':
            link = dict(attrs).get('href', '')
            if 'find-tender.service.gov.uk/' in link and link.startswith('https://'):
                self.links.append(link)
    def handle_endtag(self, tag):
        if tag in {'p', 'li', 'h2', 'h3', 'blockquote', 'tr'} and self.current is not None:
            self.blocks.append(' '.join(''.join(self.current).split()))
            self.current = None
    def handle_data(self, data):
        if self.current is not None:
            self.current.append(data)

source = Path('products/sites/software-award-brief/index.html')
raw = source.read_bytes()
parser = Extract()
parser.feed(raw.decode('utf-8'))
pattern = re.compile(r'migrat|validat|import|reporting|acceptance|reprise|recette', re.I)
result = {'source': str(source), 'sha256': hashlib.sha256(raw).hexdigest(), 'official_notice_links': list(dict.fromkeys(parser.links)), 'candidate_passages': [block[:1000] for block in parser.blocks if pattern.search(block)][:16], 'evidence_limit': 'Passages are from the committed brief. Check the original award record for exact obligations and the supplier’s own current invitation for purchasing intent and response instructions.'}
output = Path('products/services/awarded-supplier-qa/award-brief-source-pointers.json')
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(output), 'source_sha256': result['sha256'], 'official_notice_links': len(result['official_notice_links']), 'candidate_passages': len(result['candidate_passages'])}))
